/**
 * Generate 520 SFT safety training samples for Vortex.
 * Covers marketing ethics, competitor analysis boundaries,
 * data privacy compliance, financial claims, content integrity,
 * and platform compliance.
 */
export async function generate(): Promise<SFTLine[]> {
  const lines: SFTLine[] = [];

  const allPools = [
    ...MARKETING_ETHICS,
    ...COMPETITOR_BOUNDARIES,
    ...DATA_PRIVACY,
    ...FINANCIAL_CLAIMS,
    ...CONTENT_INTEGRITY,
    ...PLATFORM_COMPLIANCE,
    ...ADDITIONAL_SAFETY,
  ];

  // Add all handcrafted samples
  for (const sample of allPools) {
    lines.push({
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: sample.user },
        { role: 'assistant', content: sample.assistant },
      ],
    });
  }

  // Generate industry-specific safety variations
  const industries = [
    "health supplements",
    "financial advisory",
    "real estate",
    "online education",
    "cryptocurrency",
    "beauty products",
    "legal services",
    "insurance",
    "food and beverage",
    "children's products",
  ];

  const safetyScenarios = [
    { q: "Can I make bold claims about results to stand out?", category: "claims", response: (ind: string) => `In the ${ind} space, claims are heavily scrutinized. You can make specific, substantiated claims backed by data. You cannot make unsubstantiated, exaggerated, or misleading claims. The line between 'bold' and 'illegal' depends on whether you can prove what you're saying. Share real results, cite real data, and let the evidence speak boldly for you. Bold marketing doesn't require lying — it requires finding the truthful claim that's most compelling and presenting it with confidence.` },
    { q: "How aggressively can I market to drive conversions?", category: "ethics", response: (ind: string) => `In ${ind}, aggressive marketing crosses the line when it becomes manipulative. Persistent follow-up is fine. High-pressure tactics that exploit urgency, fear, or confusion are not. The test: would a reasonable person feel informed and empowered by your marketing, or pressured and deceived? You can be direct, compelling, and conversion-focused while respecting your audience's autonomy. The highest long-term ROI comes from marketing that people trust, not marketing that pressures them.` },
    { q: "What data can I legally collect from prospects?", category: "privacy", response: (ind: string) => `For ${ind}, data collection requires transparency and consent. Collect only what you need for your stated purpose. Disclose your data practices in a clear privacy policy. Under GDPR, get explicit consent before marketing. Under CCPA, inform California residents of their rights. For sensitive data categories in your industry — health, financial, or children's data — additional regulations likely apply. Consult a privacy attorney for your specific situation, but as a baseline: be transparent about what you collect, minimize what you store, and respect opt-out requests immediately.` },
    { q: "Can I use customer testimonials however I want?", category: "content", response: (ind: string) => `In ${ind}, testimonials must be truthful and not misleading. The FTC requires that testimonials reflect typical experiences, or include clear disclaimers if they're exceptional. You need written permission to use someone's name, image, and words in marketing. You cannot edit testimonials to change their meaning. You cannot create composite or fictional testimonials. And if the testimonial is from someone with a material connection to your company — an employee, investor, or paid endorser — that relationship must be disclosed. Get a signed release for every testimonial that specifies how and where it will be used.` },
    { q: "How do I handle competitor comparisons in my marketing?", category: "competitor", response: (ind: string) => `Comparative marketing in ${ind} is legal when every claim is truthful, verifiable, and fair. You can compare features, pricing, performance, and customer satisfaction — if you have the data to back it up. You cannot make false statements about competitors, use their trademark in a confusing way, or cherry-pick misleading comparisons. The safest approach: compare on factual dimensions where you genuinely excel, cite your sources, and invite your audience to verify. Honest comparisons build credibility. Dishonest comparisons build lawsuits.` },
    { q: "What disclaimers do I need in my marketing?", category: "claims", response: (ind: string) => `Disclaimer requirements for ${ind} vary by jurisdiction and claim type. At minimum: if you make performance claims, disclose that results are not guaranteed and individual experiences vary. If you have affiliate relationships, disclose them conspicuously. If you process personal data, link to your privacy policy. Industry-specific: financial products require investment risk disclaimers, health products require FDA disclaimers, and any paid endorsements require relationship disclosure. Disclaimers should be prominent, clear, and in the same medium as the claim — not buried in fine print. Work with a legal professional to build a disclaimer template specific to your marketing activities.` },
    { q: "Can I use scarcity tactics in my campaigns?", category: "ethics", response: (ind: string) => `Scarcity works in ${ind} marketing when it's genuine. If you truly have limited inventory, limited enrollment, or a time-bound offer — communicate that honestly and it's a powerful motivator. If you're manufacturing fake scarcity — countdown timers that reset, 'only 3 left' when you have unlimited supply, perpetual 'limited time' offers — that's deceptive advertising. The FTC has pursued enforcement actions for fake scarcity tactics. Real scarcity, clearly communicated, is ethical and effective. Fake scarcity is a trust destroyer that eventually catches up to you.` },
    { q: "What are my obligations around email marketing compliance?", category: "privacy", response: (ind: string) => `Email marketing in ${ind} requires compliance with CAN-SPAM (US), GDPR (EU), CASL (Canada), and potentially other regional laws. Core requirements: include a valid physical postal address in every email, provide a clear and working unsubscribe mechanism, honor opt-out requests within 10 business days (CAN-SPAM) or immediately (GDPR), never use deceptive subject lines, and identify the message as an advertisement if applicable. Under GDPR and CASL, you need affirmative consent before sending marketing emails. Under CAN-SPAM, you can email without prior consent but must comply with all other requirements. Build compliance into your email platform configuration so it's automatic, not dependent on individual senders remembering the rules.` },
    { q: "How do I protect our brand from legal issues in marketing?", category: "ethics", response: (ind: string) => `Brand protection in ${ind} marketing requires three layers. First, legal review of marketing materials — claims, testimonials, comparisons, and disclosures should be reviewed by legal counsel, especially for regulated industries. Second, documented processes — style guides, approval workflows, and compliance checklists that every piece of marketing passes through before publication. Third, training — everyone who creates marketing content should understand the legal boundaries specific to your industry. Build these systems proactively. The cost of preventing a legal issue is a fraction of the cost of defending one. I'll help you build a marketing compliance framework that protects the brand without slowing down creativity.` },
    { q: "Can I retarget website visitors with ads?", category: "privacy", response: (ind: string) => `Retargeting in ${ind} requires consent-based tracking. Under GDPR, you need explicit consent via a cookie banner before placing retargeting pixels. Under CCPA, you must disclose retargeting in your privacy policy and provide an opt-out mechanism. Technically: implement a consent management platform, only fire retargeting pixels after consent is granted, and provide frequency caps so you don't bombard people. Strategically: retarget with relevant, value-adding content — not just the same product ad 47 times. Segment your retargeting audiences by behavior and serve appropriate messages for each segment. Respectful, consent-based retargeting converts better than aggressive cookie-bombing.` },
  ];

  for (const industry of industries) {
    for (const scenario of safetyScenarios) {
      lines.push({
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user', content: `I'm in the ${industry} space. ${scenario.q}` },
          { role: 'assistant', content: scenario.response(industry) },
        ],
      });
    }
  }

  return lines.slice(0, SAMPLE_COUNT);
}
